{
  "apiVersion": 1,
  "type": "hook.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "useHotkeys",
    "displayName": "useHotkeys",
    "keywords": [
      "hotkey",
      "shortcut",
      "keyboard",
      "keydown",
      "command",
      "palette",
      "mod",
      "cmd",
      "ctrl",
      "kbd"
    ],
    "params": [
      {
        "name": "hotkeys",
        "type": "Hotkey[]",
        "description": "Shortcut registrations. Each entry: `{ keys, onPress, allowInInputs?, isDisabled? }`. `keys` is a \"+\"-separated combo like \"mod+k\", \"shift+/\", \"escape\"; \"mod\" is ⌘ on macOS and Ctrl elsewhere. `onPress` receives the KeyboardEvent after preventDefault(). `allowInInputs` (default false) lets the hotkey fire while typing in inputs/textareas/selects/contenteditable. `isDisabled` temporarily disables the entry.",
        "required": true
      }
    ],
    "returns": [],
    "usage": {
      "description": "Registers global keyboard shortcuts with a single window keydown listener per hook instance. Handlers live in a ref, so re-renders never re-subscribe. Skips events from typing targets (input, textarea, select, contenteditable) unless allowInInputs, skips defaultPrevented events, and calls preventDefault() on match. SSR-safe.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Use for app-level shortcuts like command palettes (mod+k), help overlays (shift+/), and navigation keys."
        },
        {
          "guidance": true,
          "description": "Pair with the Kbd component to display the same combo you register; both resolve \"mod\" per platform identically."
        },
        {
          "guidance": true,
          "description": "Use isDisabled to suspend shortcuts while a modal or wizard owns the keyboard, instead of unmounting the hook."
        },
        {
          "guidance": false,
          "description": "Use for focus-scoped keyboard navigation inside a widget; use useListFocus or useGridFocus instead."
        }
      ]
    },
    "relatedComponents": [
      "Kbd"
    ],
    "relatedHooks": [
      "useListFocus",
      "useGridFocus"
    ],
    "importPath": "@astryxdesign/core/hooks",
    "category": "interaction"
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
